// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] calldata _tos, uint v) public {
        vm.assume(_tos.length > 0);
        (bool success, bytes memory ret) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, caddress, _tos, v));
        bool returned = ret.length > 0 ? abi.decode(ret, (bool)) : false;
        assertTrue(success == returned);
    }
}

